moduleTemplateTools = (moduleId) => baseModuleTemplateTools(moduleId).replace("\u67E5\u770B\u586B\u5199\u8BF4\u660E \u203A", "\u67E5\u770B\u586B\u5199\u793A\u4F8B\u53CA\u8BE6\u7EC6\u8BF4\u660E \u203A");
var templateExample = (title, body) => `<details class="module-template-example"><summary>${title}</summary><div>${body}</div></details>`;
var moduleAttachmentTemplateHelp = {
  locations: `<section><h3>\u9644\u4EF6\u6A21\u677F\u586B\u5199\u8BF4\u660E</h3><p>\u672C\u6A21\u677F\u7528\u4E8E\u628A\u5DF2\u7ECF\u786E\u8BA4\u7684\u6062\u590D\u6761\u4EF6\uFF0C\u8FDB\u4E00\u6B65\u843D\u5B9E\u5230\u5177\u4F53\u7684\u8BBF\u95EE\u5165\u53E3\u3001\u76F8\u5173\u8BBE\u5907\u548C\u4FDD\u5B58\u4F4D\u7F6E\uFF0C\u8BA9\u672A\u6765\u6062\u590D\u4EBA\u771F\u6B63\u80FD\u591F\u627E\u5230\u5E76\u53D6\u5F97\u5BF9\u5E94\u6750\u6599\u3002</p><p>\u5E73\u53F0 / \u94B1\u5305\u540D\u79F0\u3001\u8D26\u6237\u7C7B\u578B\u4EE5\u53CA Module 2 \u5DF2\u786E\u8BA4\u7684\u6062\u590D\u6761\u4EF6\uFF0C\u4F1A\u6839\u636E\u524D\u9762\u7684\u9009\u62E9\u81EA\u52A8\u5E26\u5165\u3002</p><p>\u4F60\u4E3B\u8981\u9700\u8981\u7EE7\u7EED\u8865\u5145\uFF1A</p><ul><li>\u76F8\u5173\u8BBE\u5907\uFF1B</li><li>\u8BBF\u95EE\u5165\u53E3\uFF1B</li><li>\u5177\u4F53\u4FDD\u5B58\u4F4D\u7F6E\uFF1B</li><li>\u5FC5\u8981\u7684\u67E5\u627E\u8BF4\u660E\u3002</li></ul><h3>\u5173\u4E8E\u201C\u65E0\u201D</h3><p>\u5982\u679C\u67D0\u9879\u6761\u4EF6\u5DF2\u7ECF\u786E\u8BA4\u4E0D\u5B58\u5728\u6216\u4E0D\u9002\u7528\uFF0C\u8BF7\u660E\u786E\u586B\u5199\u201C\u65E0\u201D\uFF0C\u4E0D\u8981\u7559\u7A7A\u3002\u201C\u65E0\u201D\u8868\u793A\u5DF2\u7ECF\u786E\u8BA4\uFF1B\u7A7A\u767D\u53EF\u80FD\u8BA9\u672A\u6765\u6062\u590D\u4EBA\u65E0\u6CD5\u5224\u65AD\u662F\u201C\u4E0D\u5B58\u5728\u201D\u8FD8\u662F\u201C\u9057\u6F0F\u672A\u586B\u201D\u3002</p><h3>\u4FDD\u5B58\u4F4D\u7F6E\u600E\u4E48\u5199</h3><p>\u4FDD\u5B58\u4F4D\u7F6E\u5E94\u5177\u4F53\u5230\u672A\u6765\u6062\u590D\u4EBA\u80FD\u591F\u771F\u6B63\u5B9A\u4F4D\u5E76\u53D6\u5F97\u5BF9\u5E94\u6750\u6599\u3002</p><p><strong>\u7269\u7406\u4F4D\u7F6E\u793A\u4F8B\uFF1A</strong>\u4E66\u623F\u4FDD\u9669\u67DC\uFF1B\u4E66\u684C\u5DE6\u4FA7\u7B2C\u4E8C\u4E2A\u62BD\u5C49\uFF1B\u94F6\u884C\u4FDD\u9669\u7BB1 A-12\u3002</p><p><strong>\u7535\u5B50\u4F4D\u7F6E\u793A\u4F8B\uFF1A</strong>1Password \u2192 Binance Login\uFF1B\u5907\u7528 iPhone \u2192 Authenticator\uFF1BMacBook \u2192 \u6307\u5B9A\u6587\u4EF6\u5939 / \u6587\u4EF6\u540D\u79F0\u3002</p><p><strong>\u907F\u514D\u53EA\u5199\uFF1A</strong>\u5BB6\u91CC\uFF1B\u7535\u8111\u91CC\uFF1B\u5BC6\u7801\u7BA1\u7406\u5668\uFF1B\u7EB8\u8D28\u8D44\u6599\uFF1B\u4E91\u7AEF\u3002</p><h3>\u5B89\u5168\u63D0\u9192</h3><p>\u4E0D\u8981\u5728\u6A21\u677F\u4E2D\u76F4\u63A5\u586B\u5199\u5B8C\u6574 Seed Phrase / \u52A9\u8BB0\u8BCD\u6216\u5B8C\u6574 Private Key / \u79C1\u94A5\u3002</p><h3>\u5B8C\u6210\u540E</h3><p>\u586B\u5199\u5B8C\u6210\u540E\u4FDD\u5B58 DOCX\uFF0C\u7136\u540E\u901A\u8FC7 Module 3 \u73B0\u6709\u201C\u6DFB\u52A0\u9644\u4EF6\u201D\u4E0A\u4F20\u3002</p><p>\u5982\u76F8\u5173\u4FE1\u606F\u5DF2\u5728\u6A21\u677F\u4E2D\u5B8C\u6574\u8BB0\u5F55\uFF0C\u5728\u7EBF\u586B\u5199\u90E8\u5206\u53EF\u4EE5\u7701\u7565\uFF1B\u5982\u6709\u7279\u522B\u91CD\u8981\u7684\u4F4D\u7F6E\u6216\u98CE\u9669\u63D0\u793A\uFF0C\u4E5F\u53EF\u4EE5\u7EE7\u7EED\u5728\u7EBF\u586B\u5199\u4F5C\u4E3A\u8865\u5145\u3002</p></section><section class="module-template-examples"><h3>\u9644\u4EF6\u6A21\u677F\u586B\u5199\u793A\u4F8B</h3>${templateExample("\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\u586B\u5199\u793A\u4F8B", "<h4>Binance\uFF5C\u6CE8\u518C\u90AE\u7BB1</h4><p><strong>\u5F53\u524D\u60C5\u51B5\uFF1A</strong>\u5907\u7528\u624B\u673A\u4ECD\u53EF\u8BBF\u95EE Gmail</p><p><strong>\u5177\u4F53\u4F4D\u7F6E\uFF1A</strong>\u5907\u7528\u624B\u673A\u4F4D\u4E8E\u4E66\u623F\u4FDD\u9669\u67DC</p><p><strong>\u90AE\u7BB1\u5BC6\u7801\u8BB0\u5F55\u4F4D\u7F6E\uFF1A</strong>1Password \u2192 Gmail Recovery</p><h4>2FA</h4><p><strong>\u5F53\u524D\u65B9\u5F0F\uFF1A</strong>Authenticator</p><p><strong>\u6240\u5728\u8BBE\u5907\uFF1A</strong>\u5907\u7528 iPhone</p><p><strong>\u8BBE\u5907\u4F4D\u7F6E\uFF1A</strong>\u4E66\u623F\u4FDD\u9669\u67DC</p><p><strong>\u89E3\u9501\u5BC6\u7801\u4F4D\u7F6E\uFF1A</strong>1Password \u2192 Backup iPhone</p><h4>KYC</h4><p><strong>\u62A4\u7167\u539F\u4EF6\uFF1A</strong>\u5BB6\u5EAD\u6587\u4EF6\u67DC\u7B2C\u4E8C\u5C42</p><p><strong>\u626B\u63CF\u4EF6\uFF1A</strong>\u52A0\u5BC6 U \u76D8 \u2192 Binance KYC</p>")}${templateExample("DEX / DeFi \u586B\u5199\u793A\u4F8B", "<h4>Uniswap\uFF5C\u5173\u8054\u94B1\u5305</h4><p><strong>\u5F53\u524D\u60C5\u51B5\uFF1A</strong>\u901A\u8FC7 MetaMask Main \u8FDE\u63A5</p><p><strong>\u8BBF\u95EE\u5165\u53E3\uFF1A</strong>\u5907\u7528 MacBook \u2192 \u5B98\u65B9\u7F51\u9875</p><p><strong>\u76F8\u5173\u8BBE\u5907\uFF1A</strong>\u5907\u7528 MacBook</p><p><strong>\u8BBE\u5907\u4F4D\u7F6E\uFF1A</strong>\u4E66\u623F\u4FDD\u9669\u67DC</p><p><strong>\u67E5\u627E\u8BF4\u660E\uFF1A</strong>\u5148\u786E\u8BA4\u94B1\u5305\u5730\u5740\uFF0C\u518D\u8FDE\u63A5\u534F\u8BAE\u3002</p>")}${templateExample("\u81EA\u6258\u7BA1\u94B1\u5305\u586B\u5199\u793A\u4F8B", "<h4>Ledger\uFF5C\u6062\u590D\u6750\u6599</h4><p><strong>Hardware Wallet\uFF1A</strong>\u4E66\u623F\u4FDD\u9669\u67DC</p><p><strong>Seed Phrase \u4F4D\u7F6E\uFF1A</strong>\u94F6\u884C\u4FDD\u9669\u7BB1 A-12</p><p><strong>Passphrase \u7EBF\u7D22\uFF1A</strong>1Password \u2192 Ledger Recovery Note</p><p><strong>\u67E5\u627E\u8BF4\u660E\uFF1A</strong>\u5148\u6838\u5BF9\u8BBE\u5907\u548C\u6062\u590D\u6750\u6599\u5BF9\u5E94\u7684\u94B1\u5305\u5730\u5740\u3002</p>")}${templateExample("\u591A\u7B7E\u94B1\u5305\u586B\u5199\u793A\u4F8B", "<h4>Multisig\uFF5CSigner \u4E0E Threshold</h4><p><strong>Signer \u8BBE\u5907\uFF1A</strong>Signer A \u786C\u4EF6\u94B1\u5305\u4F4D\u4E8E\u4E66\u623F\u4FDD\u9669\u67DC</p><p><strong>\u5176\u4ED6 Signer\uFF1A</strong>\u7531\u6307\u5B9A\u534F\u52A9\u4EBA\u5206\u522B\u4FDD\u7BA1</p><p><strong>Threshold\uFF1A</strong>\u8BB0\u5F55\u5728 Multisig Setup \u8BF4\u660E\u6587\u4EF6</p><p><strong>\u67E5\u627E\u8BF4\u660E\uFF1A</strong>\u5148\u786E\u8BA4\u8FBE\u5230 Threshold \u6240\u9700\u7684 Signer \u6570\u91CF\u53CA\u8054\u7CFB\u8DEF\u5F84\u3002</p>")}</section>`,
  instructions: `<section><h3>\u9644\u4EF6\u6A21\u677F\u586B\u5199\u8BF4\u660E</h3><p>\u672C\u6A21\u677F\u7528\u4E8E\u8BB0\u5F55\u5728\u5DF2\u7ECF\u627E\u5230\u6240\u9700\u6062\u590D\u6761\u4EF6\u548C\u6750\u6599\u4E4B\u540E\uFF0C\u5E94\u8BE5\u6309\u7167\u4EC0\u4E48\u987A\u5E8F\u91CD\u65B0\u767B\u5F55\u8D26\u6237\u3001\u6062\u590D\u94B1\u5305\u6216\u91CD\u65B0\u53D6\u5F97\u63A7\u5236\u6743\u3002</p><p>\u5E73\u53F0 / \u94B1\u5305\u540D\u79F0\u3001\u8D26\u6237\u7C7B\u578B\u4EE5\u53CA Module 2 \u5DF2\u786E\u8BA4\u7684\u6062\u590D\u6761\u4EF6\uFF0C\u4F1A\u6839\u636E\u524D\u9762\u7684\u9009\u62E9\u81EA\u52A8\u5E26\u5165\u3002\u4F60\u4E3B\u8981\u9700\u8981\u586B\u5199\u5B9E\u9645\u6062\u590D\u6B65\u9AA4\u3002</p><h3>\u4E24\u79CD\u6062\u590D\u573A\u666F</h3><p><strong>A\uFF5C\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u53EF\u7528\uFF1A</strong>\u4F8B\u5982\u5907\u7528\u624B\u673A\u4ECD\u53EF\u8FDB\u5165 Email\u30012FA\u3001\u4EA4\u6613\u6240 App \u6216\u94B1\u5305\u3002</p><p><strong>B\uFF5C\u539F\u6709\u8BBE\u5907\u4E0D\u53EF\u7528 / \u65B0\u8BBE\u5907\u6062\u590D\uFF1A</strong>\u4F8B\u5982\u624B\u673A\u4E22\u5931\u3001\u7535\u8111\u635F\u574F\uFF0C\u9700\u8981\u91CD\u65B0\u5B89\u88C5 App\u3001\u91CD\u65B0\u9A8C\u8BC1\u8D26\u6237\u6216\u91CD\u65B0\u6062\u590D\u94B1\u5305\u3002</p><p>\u4E24\u79CD\u60C5\u51B5\u4E0B\u7684\u6062\u590D\u8DEF\u5F84\u53EF\u80FD\u660E\u663E\u4E0D\u540C\uFF0C\u56E0\u6B64\u5EFA\u8BAE\u5206\u522B\u8BB0\u5F55\u3002</p><h3>\u6B65\u9AA4\u600E\u4E48\u5199</h3><p>\u4E00\u4E2A\u6B65\u9AA4\u53EA\u5199\u4E00\u4E2A\u52A8\u4F5C\u3002\u6BCF\u4E00\u6B65\u5C3D\u91CF\u5199\u6E05\u8981\u505A\u4EC0\u4E48\u3001\u4F7F\u7528\u4EC0\u4E48\uFF0C\u4EE5\u53CA\u5B8C\u6210\u4EE5\u540E\u5E94\u8BE5\u770B\u5230\u4EC0\u4E48\u7ED3\u679C\u3002</p><h3>\u5982\u679C\u5173\u952E\u6062\u590D\u6761\u4EF6\u672C\u8EAB\u5931\u6548</h3><p>\u4E0D\u8981\u53EA\u8BB0\u5F55\u6B63\u5E38\u60C5\u51B5\u4E0B\u7684\u6062\u590D\u8DEF\u5F84\u3002\u7279\u522B\u662F\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\uFF0C\u53EF\u4EE5\u8003\u8651\u6CE8\u518C\u90AE\u7BB1\u3001\u767B\u5F55\u5BC6\u7801\u30012FA\u3001\u624B\u673A\u53F7\u3001KYC \u6216\u53EF\u4FE1\u8BBE\u5907\u65E0\u6CD5\u4F7F\u7528\u65F6\u7684\u5907\u7528\u8DEF\u5F84\u3002\u5177\u4F53\u5907\u7528\u8DEF\u5F84\u5E94\u4EE5\u5E73\u53F0 / \u94B1\u5305\u771F\u5B9E\u8D26\u6237\u8BBE\u7F6E\u548C\u5B98\u65B9\u6062\u590D\u6D41\u7A0B\u4E3A\u51C6\u3002</p><h3>\u907F\u514D\u5355\u4E00\u624B\u673A\u6210\u4E3A\u552F\u4E00\u6062\u590D\u6761\u4EF6</h3><p>\u5982\u679C\u624B\u673A\u540C\u65F6\u627F\u62C5 Email\u3001\u77ED\u4FE1\u9A8C\u8BC1\u30012FA\u3001\u53EF\u4FE1\u8BBE\u5907\u7B49\u591A\u4E2A\u6062\u590D\u529F\u80FD\uFF0C\u5EFA\u8BAE\u786E\u8BA4\u4ECD\u6709\u5176\u4ED6\u53EF\u6267\u884C\u7684\u6062\u590D\u65B9\u5F0F\u3002</p><h3>\u5907\u7528\u6062\u590D\u8BBE\u5907\u4E0E\u4EBA\u8138\u8BC6\u522B</h3><p>\u5907\u7528\u6062\u590D\u8BBE\u5907\u4E0D\u5EFA\u8BAE\u628A\u8D26\u6237\u672C\u4EBA\u7684<span class="module-example-emphasis">\u4EBA\u8138\u8BC6\u522B</span>\u6216\u5176\u4ED6\u672C\u4EBA\u4E13\u5C5E\u751F\u7269\u8BC6\u522B\uFF0C\u4F5C\u4E3A\u8FDB\u5165\u5173\u952E\u6062\u590D\u5DE5\u5177\u7684\u552F\u4E00\u65B9\u5F0F\u3002</p><p>\u5982\u679C\u5907\u7528\u8BBE\u5907\u7528\u4E8E\u672A\u6765\u6062\u590D\uFF0C\u5E94\u786E\u4FDD\u672A\u6765\u6062\u590D\u4EBA\u4ECD\u53EF\u4EE5\u901A\u8FC7\u8BBE\u5907\u5BC6\u7801\u3001App \u5BC6\u7801\u3001Passkey \u6216\u5176\u4ED6\u5B89\u5168\u65B9\u5F0F\u8FDB\u5165\u90AE\u7BB1\u30012FA\u3001\u94B1\u5305\u7B49\u5173\u952E\u5DE5\u5177\u3002</p><p>\u65E5\u5E38\u4F7F\u7528\u8BBE\u5907\u4ECD\u53EF\u7EE7\u7EED\u4F7F\u7528\u4EBA\u8138\u8BC6\u522B\u7B49\u5B89\u5168\u4FDD\u62A4\uFF1B\u8FD9\u91CC\u5F3A\u8C03\u7684\u662F\uFF0C\u4E13\u95E8\u7528\u4E8E\u672A\u6765\u6062\u590D\u7684\u5907\u7528\u8BBE\u5907\uFF0C\u5E94\u907F\u514D\u672C\u4EBA\u4E13\u5C5E\u751F\u7269\u8BC6\u522B\u6210\u4E3A\u6062\u590D\u969C\u788D\u3002</p><h3>\u5B89\u5168\u63D0\u9192</h3><p>\u8BB0\u5F55\u64CD\u4F5C\u65B9\u5F0F\u548C\u6062\u590D\u987A\u5E8F\u5373\u53EF\u3002\u4E0D\u8981\u5728\u6A21\u677F\u4E2D\u76F4\u63A5\u586B\u5199\u5B8C\u6574 Seed Phrase \u6216\u5B8C\u6574 Private Key\u3002</p><h3>\u5B8C\u6210\u540E</h3><p>\u586B\u5199\u5B8C\u6210\u540E\u4FDD\u5B58 DOCX\uFF0C\u7136\u540E\u901A\u8FC7 Module 4 \u73B0\u6709\u201C\u6DFB\u52A0\u9644\u4EF6\u201D\u4E0A\u4F20\u3002</p><p>\u5982\u6062\u590D\u6B65\u9AA4\u5DF2\u5728\u6A21\u677F\u4E2D\u5B8C\u6574\u8BB0\u5F55\uFF0C\u5728\u7EBF\u586B\u5199\u90E8\u5206\u53EF\u4EE5\u7701\u7565\uFF1B\u5982\u6709\u7279\u522B\u91CD\u8981\u7684\u6B65\u9AA4\u3001\u98CE\u9669\u70B9\u6216\u5907\u7528\u65B9\u6848\uFF0C\u4E5F\u53EF\u4EE5\u7EE7\u7EED\u5728\u7EBF\u586B\u5199\u4F5C\u4E3A\u8865\u5145\u3002</p></section><section class="module-template-examples"><h3>\u9644\u4EF6\u6A21\u677F\u586B\u5199\u793A\u4F8B</h3>${templateExample("\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\u586B\u5199\u793A\u4F8B", "<h4>Binance\uFF5CA\uFF5C\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u53EF\u7528</h4><ol><li><strong>Step 1\uFF1A</strong>\u627E\u5230\u539F\u6709 / \u5907\u7528\u5DF2\u4FE1\u4EFB\u8BBE\u5907\u3002<br>\u7ED3\u679C\uFF1A\u8BBE\u5907\u53EF\u6B63\u5E38\u89E3\u9501\u3002</li><li><strong>Step 2\uFF1A</strong>\u6253\u5F00\u4EA4\u6613\u6240\u5B98\u65B9 App / \u5B98\u7F51\u3002<br>\u7ED3\u679C\uFF1A\u786E\u8BA4\u4F7F\u7528\u5B98\u65B9\u5165\u53E3\u3002</li><li><strong>Step 3\uFF1A</strong>\u8F93\u5165\u4EA4\u6613\u6240\u767B\u5F55\u4FE1\u606F\u3002<br>\u7ED3\u679C\uFF1A\u8D26\u6237\u4FE1\u606F\u5339\u914D\u3002</li><li><strong>Step 4\uFF1A</strong>\u5B8C\u6210\u6CE8\u518C\u90AE\u7BB1\u9A8C\u8BC1\u3002<br>\u7ED3\u679C\uFF1A\u90AE\u7BB1\u8BBF\u95EE\u6B63\u5E38\u3002</li><li><strong>Step 5\uFF1A</strong>\u5B8C\u6210 2FA\u3002<br>\u7ED3\u679C\uFF1A\u9A8C\u8BC1\u6210\u529F\u3002</li><li><strong>Step 6\uFF1A</strong>\u5982\u5E73\u53F0\u8981\u6C42\uFF0C\u5B8C\u6210\u5176\u4ED6\u5B89\u5168\u9A8C\u8BC1\u3002<br>\u7ED3\u679C\uFF1A\u8FDB\u5165\u8D26\u6237\u3002</li><li><strong>Step 7\uFF1A</strong>\u6838\u5BF9\u8D26\u6237\u8EAB\u4EFD\u3001\u8D44\u4EA7\u548C\u5B89\u5168\u8BBE\u7F6E\u3002<br>\u7ED3\u679C\uFF1A\u786E\u8BA4\u8D26\u6237\u6B63\u5E38\u3002</li></ol><h4>B\uFF5C\u539F\u6709\u8BBE\u5907\u4E0D\u53EF\u7528 / \u65B0\u8BBE\u5907\u6062\u590D</h4><ol><li>\u5728\u65B0\u8BBE\u5907\u6253\u5F00\u5B98\u65B9\u5165\u53E3\u3002</li><li>\u4F7F\u7528\u5DF2\u786E\u8BA4\u7684\u767B\u5F55\u4E0E\u90AE\u7BB1\u6062\u590D\u6761\u4EF6\u3002</li><li>\u6309\u5E73\u53F0\u6D41\u7A0B\u5B8C\u6210 2FA \u91CD\u7F6E\u6216\u8EAB\u4EFD\u9A8C\u8BC1\u3002</li><li>\u8FDB\u5165\u8D26\u6237\u540E\u6838\u5BF9\u8EAB\u4EFD\u3001\u8D44\u4EA7\u548C\u5B89\u5168\u8BBE\u7F6E\u3002</li></ol>")}${templateExample("DEX / DeFi \u586B\u5199\u793A\u4F8B", "<h4>Uniswap\uFF5C\u6062\u590D\u8DEF\u5F84</h4><ol><li>\u5148\u6062\u590D\u5E76\u6838\u5BF9\u5173\u8054\u94B1\u5305\u3002</li><li>\u4ECE\u5B98\u65B9\u5165\u53E3\u8FDE\u63A5\u534F\u8BAE\u3002</li><li>\u6838\u5BF9\u94B1\u5305\u5730\u5740\u3001\u7F51\u7EDC\u548C\u5DF2\u6388\u6743\u8FDE\u63A5\u3002</li><li>\u786E\u8BA4\u94FE\u4E0A\u8D44\u4EA7\u548C\u5934\u5BF8\u6B63\u5E38\u663E\u793A\u3002</li></ol>")}${templateExample("\u81EA\u6258\u7BA1\u94B1\u5305\u586B\u5199\u793A\u4F8B", "<h4>Ledger / MetaMask\uFF5C\u65B0\u8BBE\u5907\u6062\u590D</h4><ol><li>\u5728\u65B0\u8BBE\u5907\u5B89\u88C5\u5B98\u65B9\u94B1\u5305\u5E94\u7528\u3002</li><li>\u4F7F\u7528\u5BF9\u5E94 Seed Phrase \u6062\u590D\u94B1\u5305\uFF1B\u5982\u5B9E\u9645\u542F\u7528 Passphrase\uFF0C\u518D\u6062\u590D\u5BF9\u5E94\u8D26\u6237\u3002</li><li>\u8BBE\u7F6E\u65B0\u7684\u8BBE\u5907\u6216 App \u8BBF\u95EE\u5BC6\u7801\u3002</li><li>\u6838\u5BF9\u94B1\u5305\u5730\u5740\u540E\u518D\u786E\u8BA4\u8D44\u4EA7\u4FE1\u606F\u3002</li></ol>")}${templateExample("\u591A\u7B7E\u94B1\u5305\u586B\u5199\u793A\u4F8B", "<h4>Multisig\uFF5CThreshold \u6062\u590D</h4><ol><li>\u786E\u8BA4\u9700\u8981\u6062\u590D\u7684\u591A\u7B7E\u5730\u5740\u548C Threshold\u3002</li><li>\u6062\u590D\u8FBE\u5230 Threshold \u6570\u91CF\u7684 Signer\u3002</li><li>\u4F7F\u7528\u5B98\u65B9\u6216\u5DF2\u786E\u8BA4\u5165\u53E3\u521B\u5EFA\u63D0\u6848\u3002</li><li>\u7531\u8DB3\u591F Signer \u6838\u5BF9\u5E76\u7B7E\u540D\u3002</li><li>\u8FBE\u5230 Threshold \u540E\u6267\u884C\u5E76\u6838\u5BF9\u7ED3\u679C\u3002</li></ol>")}</section>`
};
var moduleExampleContent = {
  accounts: { title: "Module 1\uFF5C\u8D44\u4EA7\u4E0E\u8D26\u6237\u586B\u5199\u793A\u4F8B", body: "<section><h3>\u586B\u5199\u63D0\u9192</h3><p>\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\u9664\u4E86\u9009\u62E9\u5E73\u53F0\u540D\u79F0\u5916\uFF0C\u8FD8\u9700\u8981\u989D\u5916\u9009\u62E9\uFF1A</p><ul><li>\u8D26\u6237\u6240\u5728\u533A\u57DF\uFF1B</li><li>\u8D26\u6237\u7C7B\u578B\uFF08\u4E2A\u4EBA\u8D26\u6237 / \u673A\u6784\u8D26\u6237\uFF09\u3002</li></ul><p>\u8FD9\u4E24\u9879\u5C5E\u4E8E\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\u7684\u5FC5\u8981\u586B\u5199\u5185\u5BB9\u3002</p><p>\u5176\u4ED6\u7C7B\u578B\u7684\u5E73\u53F0\u6216\u94B1\u5305\uFF0C\u6309\u5B9E\u9645\u4F7F\u7528\u60C5\u51B5\u76F4\u63A5\u9009\u62E9\u5373\u53EF\u3002</p><p>\u540C\u4E00\u5E73\u53F0\u5B58\u5728\u591A\u4E2A\u72EC\u7ACB\u8D26\u6237\u65F6\uFF0C\u53EF\u5206\u522B\u6DFB\u52A0\u3002</p></section><section><h3>\u586B\u5199\u793A\u4F8B</h3><dl><div><dt>\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240</dt><dd>Binance\uFF5C\u6FB3\u6D32\uFF5C\u4E2A\u4EBA\u8D26\u6237</dd></div><div><dt>\u70ED\u94B1\u5305 / \u8F6F\u4EF6\u94B1\u5305</dt><dd>MetaMask</dd></div><div><dt>\u51B7\u94B1\u5305 / \u786C\u4EF6\u94B1\u5305</dt><dd>Ledger</dd></div><div><dt>DEX / DeFi</dt><dd>Uniswap</dd></div></dl></section><section><h3>\u8BF4\u660E</h3><p>\u793A\u4F8B\u4EC5\u7528\u4E8E\u5E2E\u52A9\u7406\u89E3\u9009\u62E9\u548C\u586B\u5199\u65B9\u5F0F\uFF0C\u8BF7\u6309\u7167\u81EA\u5DF1\u7684\u5B9E\u9645\u8D26\u6237\u60C5\u51B5\u8FDB\u884C\u9009\u62E9\u548C\u586B\u5199\u3002</p></section>" },
  conditions: { title: "Module 2\uFF5C\u6062\u590D\u6240\u9700\u6761\u4EF6\u586B\u5199\u793A\u4F8B", body: '<section><h3>\u586B\u5199\u63D0\u9192</h3><p>\u4E0D\u540C\u8D26\u6237\u7C7B\u578B\u6240\u9700\u7684\u6062\u590D\u6761\u4EF6\u53EF\u80FD\u4E0D\u540C\uFF0C\u8BF7\u4EE5\u5F53\u524D\u8D26\u6237\u7684\u771F\u5B9E\u8BBE\u7F6E\u4E3A\u51C6\u9010\u9879\u786E\u8BA4\u3002</p><p>\u5173\u952E\u6062\u590D\u6761\u4EF6\u5E94\u5C3D\u91CF\u907F\u514D\u9057\u6F0F\u3002</p><p>\u5982\u679C\u4E0D\u786E\u5B9A\u67D0\u9879\u6761\u4EF6\u662F\u5426\u771F\u6B63\u9700\u8981\uFF0C\u5EFA\u8BAE\u901A\u8FC7\uFF1A</p><ul><li>\u5B9E\u9645\u767B\u5F55\u68C0\u67E5\uFF1B</li><li>\u8F7B\u91CF\u6062\u590D\u6F14\u7EC3\uFF1B</li><li>\u5E73\u53F0\u6216\u94B1\u5305\u5B98\u65B9\u8D44\u6599\uFF1B</li></ul><p>\u8FDB\u4E00\u6B65\u786E\u8BA4\u3002</p><ul><li><strong>\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\uFF1A</strong>\u91CD\u70B9\u786E\u8BA4\u8D26\u6237\u767B\u5F55\u30012FA\u3001\u8EAB\u4EFD\u9A8C\u8BC1\u4EE5\u53CA\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u7B49\u6062\u590D\u6761\u4EF6\uFF1B</li><li><strong>DEX / DeFi\uFF1A</strong>\u91CD\u70B9\u786E\u8BA4\u5B9E\u9645\u4F7F\u7528\u7684\u94B1\u5305\u65B9\u5F0F\uFF0C\u4EE5\u53CA\u5BF9\u5E94\u7684\u94B1\u5305\u6216\u8D26\u6237\u6062\u590D\u6761\u4EF6\uFF1B</li><li><strong>\u81EA\u6258\u7BA1\u94B1\u5305\uFF1A</strong>\u91CD\u70B9\u786E\u8BA4\u771F\u6B63\u7528\u4E8E\u91CD\u65B0\u53D6\u5F97\u94B1\u5305\u63A7\u5236\u6743\u7684\u6062\u590D\u6750\u6599\uFF1B</li><li><strong>\u591A\u7B7E\uFF1A</strong>\u5982\u679C\u4F7F\u7528\u591A\u7B7E\uFF0C\u8FD8\u9700\u786E\u8BA4 Signer \u548C Threshold \u7B49\u8054\u5408\u7B7E\u540D\u6761\u4EF6\u3002</li></ul><h3>\u4EC0\u4E48\u662F\u201C\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u201D\uFF1F</h3><p>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF0C\u662F\u6307\u5F53\u524D\u6B63\u5728\u4F7F\u7528\uFF0C\u6216\u4E3A\u672A\u6765\u6062\u590D\u9884\u5148\u51C6\u5907\u7684\u624B\u673A\u3001\u7535\u8111\u6216\u5176\u4ED6\u8BBE\u5907\u3002</p><p>\u8FD9\u4E9B\u8BBE\u5907\u53EF\u80FD\u5DF2\u7ECF\u5B89\u88C5\u5E76\u914D\u7F6E\u4EA4\u6613\u6240\u3001\u94B1\u5305\u3001\u90AE\u7BB1\u30012FA \u7B49\u5173\u952E\u5DE5\u5177\uFF0C\u4E5F\u53EF\u80FD\u4FDD\u7559\u5DF2\u767B\u5F55\u3001\u5DF2\u914D\u7F6E\u6216\u53EF\u4FE1\u8BBE\u5907\u72B6\u6001\u3002</p><p>\u5982\u679C\u8FD9\u4E9B\u8BBE\u5907\u672A\u6765\u4ECD\u80FD\u6B63\u5E38\u5F00\u673A\u3001\u89E3\u9501\u5E76\u8BBF\u95EE\u76F8\u5173\u5DE5\u5177\uFF0C\u901A\u5E38\u53EF\u4EE5\u660E\u663E\u964D\u4F4E\u6062\u590D\u96BE\u5EA6\u3002</p><p>\u5EFA\u8BAE\u5B9A\u671F\u786E\u8BA4\u5907\u7528\u8BBE\u5907\u4ECD\u53EF\u6B63\u5E38\u4F7F\u7528\uFF0C\u5E76\u786E\u4FDD\u76F8\u5173 App\u3001\u90AE\u7BB1\u548C 2FA \u7B49\u5173\u952E\u5DE5\u5177\u4ECD\u7136\u6709\u6548\u3002</p><h3>\u6062\u590D\u8BBE\u5907\u5EFA\u8BAE</h3><p>\u65E5\u5E38\u4F7F\u7528\u8BBE\u5907\u53EF\u4EE5\u7EE7\u7EED\u4F7F\u7528\u4EBA\u8138\u8BC6\u522B\u7B49\u5B89\u5168\u4FDD\u62A4\uFF1B\u5982\u679C\u67D0\u53F0\u8BBE\u5907\u4E13\u95E8\u4F5C\u4E3A\u672A\u6765\u6062\u590D\u7684\u5907\u7528\u8BBE\u5907\uFF0C\u5EFA\u8BAE\u786E\u8BA4\u90AE\u7BB1\u30012FA\u3001\u94B1\u5305\u7B49\u5173\u952E App \u4E0D\u4F1A\u56E0\u4E3A\u53EA\u80FD\u8BC6\u522B\u8D26\u6237\u672C\u4EBA\u800C\u5BFC\u81F4\u6062\u590D\u4EBA\u65E0\u6CD5\u8FDB\u5165\u3002</p><p>\u5FC5\u8981\u65F6\u53EF\u6539\u7528\u8BBE\u5907\u5BC6\u7801\u3001App \u5BC6\u7801\u3001Passkey \u6216\u5176\u4ED6\u53EF\u6267\u884C\u7684\u5B89\u5168\u8BBF\u95EE\u65B9\u5F0F\uFF0C\u5728\u65E5\u5E38\u5B89\u5168\u4E0E\u672A\u6765\u53EF\u6062\u590D\u6027\u4E4B\u95F4\u4FDD\u6301\u5E73\u8861\u3002</p></section><section><h3>\u586B\u5199\u793A\u4F8B</h3><div class="module-example-cases"><article><strong>\u793A\u4F8B 1\uFF5CBinance</strong><ul><li>\u6CE8\u518C\u90AE\u7BB1</li><li>\u4EA4\u6613\u6240\u767B\u5F55\u5BC6\u7801</li><li>2FA</li><li>KYC / \u8EAB\u4EFD\u8D44\u6599</li><li>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF08\u5982\u5907\u7528\u624B\u673A\u3001\u5907\u7528\u7535\u8111\uFF09</li></ul></article><article><strong>\u793A\u4F8B 2\uFF5CLedger</strong><ul><li>Hardware Wallet / \u786C\u4EF6\u94B1\u5305</li><li>Seed Phrase / \u52A9\u8BB0\u8BCD</li><li>Passphrase / \u989D\u5916\u53E3\u4EE4</li><li>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF08\u5982\u5907\u7528\u624B\u673A\u3001\u5907\u7528\u7535\u8111\uFF09</li></ul></article><article><strong>\u793A\u4F8B 3\uFF5CMetaMask</strong><ul><li>Seed Phrase / \u52A9\u8BB0\u8BCD</li><li>\u94B1\u5305\u8BBF\u95EE\u5BC6\u7801</li><li>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF08\u5982\u5907\u7528\u624B\u673A\u3001\u5907\u7528\u7535\u8111\uFF09</li></ul></article></div></section><section><h3>\u8BF4\u660E</h3><p>\u793A\u4F8B\u4EC5\u7528\u4E8E\u5E2E\u52A9\u7406\u89E3\u6062\u590D\u6761\u4EF6\u7684\u9009\u62E9\u65B9\u5F0F\u3002\u4E0D\u540C\u5E73\u53F0\u548C\u94B1\u5305\u7684\u771F\u5B9E\u6062\u590D\u6761\u4EF6\u53EF\u80FD\u4E0D\u540C\uFF0C\u8BF7\u6839\u636E\u81EA\u5DF1\u7684\u5B9E\u9645\u8D26\u6237\u8BBE\u7F6E\u8FDB\u884C\u786E\u8BA4\u548C\u9009\u62E9\u3002</p></section>' },
  locations: { title: "Module 3\uFF5C\u4F4D\u7F6E\u4E0E\u67E5\u627E\u586B\u5199\u793A\u4F8B\u53CA\u8BE6\u7EC6\u8BF4\u660E", body: '<section><h3>\u4EC0\u4E48\u662F\u201C\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u201D</h3><p>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF0C\u662F\u6307\u5F53\u524D\u6B63\u5728\u4F7F\u7528\uFF0C\u6216\u4E3A\u672A\u6765\u6062\u590D\u9884\u5148\u51C6\u5907\u7684\u624B\u673A\u3001\u7535\u8111\u6216\u5176\u4ED6\u8BBE\u5907\u3002\u8FD9\u4E9B\u8BBE\u5907\u53EF\u80FD\u5DF2\u7ECF\u5B89\u88C5\u5E76\u914D\u7F6E\u4EA4\u6613\u6240\u3001\u94B1\u5305\u3001\u90AE\u7BB1\u30012FA \u7B49\u5173\u952E\u5DE5\u5177\uFF0C\u4E5F\u53EF\u80FD\u4FDD\u7559\u5DF2\u767B\u5F55\u3001\u5DF2\u914D\u7F6E\u6216\u53EF\u4FE1\u8BBE\u5907\u72B6\u6001\u3002</p><p>\u5728\u672C\u6A21\u5757\u4E2D\uFF0C\u8BF7\u8BB0\u5F55\u8FD9\u4E9B\u8BBE\u5907\u672C\u8EAB\u5728\u54EA\u91CC\uFF0C\u4EE5\u53CA\u672A\u6765\u6062\u590D\u4EBA\u5982\u4F55\u5B89\u5168\u627E\u5230\u5E76\u8BBF\u95EE\u5B83\u4EEC\u3002</p></section><section><h3>\u4FDD\u5B58\u4F4D\u7F6E\u600E\u6837\u624D\u7B97\u201C\u53EF\u627E\u5230\u201D</h3><p>\u4FDD\u5B58\u4F4D\u7F6E\u5E94\u5177\u4F53\u5230\u672A\u6765\u6062\u590D\u4EBA\u80FD\u591F\u771F\u6B63\u5B9A\u4F4D\u5E76\u53D6\u5F97\u5BF9\u5E94\u6750\u6599\u3002</p><div class="module-example-subgroup"><strong>\u5177\u4F53\u63CF\u8FF0\u793A\u4F8B</strong><p>\u7269\u7406\u4F4D\u7F6E\uFF1A</p><ul><li>\u4E66\u623F\u4FDD\u9669\u67DC</li><li>\u5367\u5BA4\u8863\u67DC\u4E0A\u5C42\u5BC6\u7801\u76D2</li><li>\u94F6\u884C\u4FDD\u9669\u7BB1 A-12</li></ul><p>\u7535\u5B50\u4F4D\u7F6E\uFF1A</p><ul><li>MacBook \u4E0A\u7684 1Password \u2192 Binance Login</li><li>\u5907\u7528 iPhone \u4E2D\u7684 Authenticator</li></ul></div><div class="module-example-subgroup"><strong>\u8FC7\u4E8E\u62BD\u8C61\u7684\u63CF\u8FF0\u793A\u4F8B</strong><ul><li>\u5BB6\u91CC</li><li>\u7535\u8111\u91CC</li><li>\u5BC6\u7801\u7BA1\u7406\u5668</li><li>\u7EB8\u8D28\u8D44\u6599</li><li>\u4E91\u7AEF</li></ul></div><p>\u8FD9\u7C7B\u8FC7\u4E8E\u62BD\u8C61\u7684\u63CF\u8FF0\u901A\u5E38\u4E0D\u8DB3\u4EE5\u8BA9\u672A\u6765\u6062\u590D\u4EBA\u51C6\u786E\u5B9A\u4F4D\u6750\u6599\uFF0C\u56E0\u6B64\u5E94\u5C3D\u91CF\u8BB0\u5F55\u66F4\u5177\u4F53\u7684\u4F4D\u7F6E\u6216\u8BBF\u95EE\u8DEF\u5F84\u3002</p></section><section><h3>\u586B\u5199\u793A\u4F8B</h3><div class="module-example-cases"><article><strong>\u793A\u4F8B 1\uFF5CBinance</strong><ul><li>\u6CE8\u518C\u90AE\u7BB1\uFF1AGmail</li><li>2FA\uFF1A\u5907\u7528 iPhone</li><li>KYC \u8D44\u6599\uFF1A\u4E66\u623F\u6587\u4EF6\u67DC\u7B2C\u4E8C\u5C42</li><li>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF1A\u5907\u7528 iPhone\uFF0C\u4E66\u623F\u4FDD\u9669\u67DC</li></ul></article><article><strong>\u793A\u4F8B 2\uFF5CMetaMask</strong><ul><li>Seed Phrase\uFF1A\u4E66\u623F\u4FDD\u9669\u67DC</li><li>\u94B1\u5305\u8BBF\u95EE\u5BC6\u7801\uFF1A\u5BC6\u7801\u7BA1\u7406\u5668 \u2192 MetaMask Main</li><li>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\uFF1A\u5907\u7528 MacBook</li></ul></article><article><strong>\u793A\u4F8B 3\uFF5CLedger</strong><ul><li>Hardware Wallet\uFF1A\u4E66\u623F\u4FDD\u9669\u67DC</li><li>Seed Phrase\uFF1A\u94F6\u884C\u4FDD\u9669\u7BB1</li><li>Passphrase\uFF1A\u5BC6\u7801\u7BA1\u7406\u5668\u4E2D\u7684\u6307\u5B9A\u6761\u76EE</li></ul></article></div></section><section><h3>\u6062\u590D\u8BBE\u5907\u5EFA\u8BAE</h3><p>\u65E5\u5E38\u4F7F\u7528\u8BBE\u5907\u53EF\u4EE5\u7EE7\u7EED\u4F7F\u7528\u4EBA\u8138\u8BC6\u522B\u7B49\u5B89\u5168\u4FDD\u62A4\uFF1B\u5982\u679C\u67D0\u53F0\u8BBE\u5907\u4E13\u95E8\u4F5C\u4E3A\u672A\u6765\u6062\u590D\u7684\u5907\u7528\u8BBE\u5907\uFF0C\u5EFA\u8BAE\u786E\u8BA4\u90AE\u7BB1\u30012FA\u3001\u94B1\u5305\u7B49\u5173\u952E App \u4E0D\u4F1A\u56E0\u4E3A\u53EA\u80FD\u8BC6\u522B\u8D26\u6237\u672C\u4EBA\u800C\u5BFC\u81F4\u6062\u590D\u4EBA\u65E0\u6CD5\u8FDB\u5165\u3002</p><p>\u5FC5\u8981\u65F6\u53EF\u4F7F\u7528\u8BBE\u5907\u5BC6\u7801\u3001App \u5BC6\u7801\u3001Passkey \u6216\u5176\u4ED6\u53EF\u6267\u884C\u7684\u5B89\u5168\u8BBF\u95EE\u65B9\u5F0F\uFF0C\u5728\u65E5\u5E38\u5B89\u5168\u4E0E\u672A\u6765\u53EF\u6062\u590D\u6027\u4E4B\u95F4\u4FDD\u6301\u5E73\u8861\u3002</p></section>' },
  instructions: { title: "Module 4\uFF5C\u6062\u590D\u4E0E\u8F6C\u79FB\u6B65\u9AA4\u586B\u5199\u793A\u4F8B\u53CA\u8BE6\u7EC6\u8BF4\u660E", body: '<section><h3>\u4E24\u79CD\u6062\u590D\u573A\u666F</h3><article><strong>\u73B0\u6709 / \u5907\u7528\u8BBE\u5907\u53EF\u7528</strong><p>\u6307\u5F53\u524D\u8BBE\u5907\u6216\u9884\u5148\u51C6\u5907\u7684\u5907\u7528\u624B\u673A\u3001\u7535\u8111\u4ECD\u53EF\u6B63\u5E38\u4F7F\u7528\uFF0C\u5E76\u80FD\u591F\u8FDB\u5165\u76F8\u5173\u90AE\u7BB1\u30012FA\u3001\u4EA4\u6613\u6240 App\u3001\u94B1\u5305\u6216\u5176\u4ED6\u5173\u952E\u6062\u590D\u5DE5\u5177\u3002</p><p>\u5728\u8FD9\u79CD\u60C5\u51B5\u4E0B\uFF0C\u53EF\u4EE5\u4F18\u5148\u5229\u7528\u5DF2\u6709\u767B\u5F55\u72B6\u6001\u3001\u53EF\u4FE1\u8BBE\u5907\u6216\u5DF2\u7ECF\u914D\u7F6E\u597D\u7684\u6062\u590D\u5DE5\u5177\uFF0C\u6062\u590D\u8DEF\u5F84\u901A\u5E38\u66F4\u77ED\u3002</p></article><article><strong>\u539F\u6709\u8BBE\u5907\u4E0D\u53EF\u7528 / \u65B0\u8BBE\u5907\u6062\u590D</strong><p>\u5982\u679C\u539F\u6709\u624B\u673A\u3001\u7535\u8111\u4E22\u5931\u3001\u635F\u574F\u6216\u65E0\u6CD5\u8BBF\u95EE\uFF0C\u5219\u9700\u8981\u5728\u65B0\u8BBE\u5907\u4E0A\u91CD\u65B0\u5EFA\u7ACB\u6062\u590D\u73AF\u5883\u3002</p><p>\u6B64\u65F6\u53EF\u80FD\u9700\u8981\u4F7F\u7528\uFF1A</p><ul><li>Email</li><li>\u767B\u5F55\u5BC6\u7801</li><li>2FA Recovery Code</li><li>KYC</li><li>Seed Phrase</li><li>Private Key</li><li>Passphrase</li><li>Hardware Wallet</li></ul><p>\u5177\u4F53\u4EE5\u771F\u5B9E\u8D26\u6237\u8BBE\u7F6E\u4E3A\u51C6\u3002</p></article></section><section><h3>\u5982\u679C\u5173\u952E\u6062\u590D\u6761\u4EF6\u672C\u8EAB\u65E0\u6CD5\u4F7F\u7528</h3><p>\u8BB0\u5F55\u6062\u590D\u6B65\u9AA4\u65F6\uFF0C\u4E0D\u4EC5\u8981\u5199\u6B63\u5E38\u8DEF\u5F84\uFF0C\u4E5F\u5EFA\u8BAE\u8003\u8651\u5173\u952E\u6062\u590D\u6761\u4EF6\u672C\u8EAB\u5931\u6548\u65F6\u7684\u5907\u7528\u8DEF\u5F84\u3002</p><p>\u7279\u522B\u662F\u4E2D\u5FC3\u5316\u4EA4\u6613\u6240\uFF0C\u53EF\u4EE5\u786E\u8BA4\uFF1A</p><ul><li>\u6CE8\u518C\u90AE\u7BB1\u65E0\u6CD5\u767B\u5F55\u65F6\uFF0C\u90AE\u7BB1\u81EA\u8EAB\u5982\u4F55\u6062\u590D\uFF1B</li><li>\u5FD8\u8BB0\u4EA4\u6613\u6240\u767B\u5F55\u5BC6\u7801\u65F6\uFF0C\u5E73\u53F0\u5BC6\u7801\u627E\u56DE\u8DEF\u5F84\uFF1B</li><li>2FA \u8BBE\u5907\u4E22\u5931\u6216 Authenticator \u65E0\u6CD5\u4F7F\u7528\u65F6\uFF0C\u662F\u5426\u6709 2FA \u6062\u590D\u7801\u6216\u5E73\u53F0\u91CD\u7F6E\u6D41\u7A0B\uFF1B</li><li>\u6CE8\u518C\u624B\u673A\u53F7\u4E0D\u53EF\u7528\u65F6\uFF0C\u662F\u5426\u6709\u5176\u4ED6\u9A8C\u8BC1\u65B9\u5F0F\uFF1B</li><li>KYC \u88AB\u89E6\u53D1\u65F6\uFF0C\u9700\u8981\u51C6\u5907\u54EA\u4E9B\u8EAB\u4EFD\u8D44\u6599\uFF1B</li><li>\u53EF\u4FE1\u8BBE\u5907\u5931\u6548\u65F6\uFF0C\u5982\u4F55\u5728\u65B0\u8BBE\u5907\u91CD\u65B0\u5EFA\u7ACB\u53EF\u4FE1\u72B6\u6001\u3002</li></ul><p>\u5177\u4F53\u6062\u590D\u65B9\u5F0F\u8BF7\u4EE5\u5BF9\u5E94\u5E73\u53F0\u6216\u94B1\u5305\u7684\u771F\u5B9E\u8D26\u6237\u8BBE\u7F6E\u548C\u5B98\u65B9\u6062\u590D\u6D41\u7A0B\u4E3A\u51C6\u3002</p></section><section><h3>\u907F\u514D\u5355\u4E00\u8BBE\u5907\u6210\u4E3A\u552F\u4E00\u6062\u590D\u6761\u4EF6</h3><p>\u5982\u679C\u624B\u673A\u540C\u65F6\u627F\u62C5\u90AE\u7BB1\u3001\u77ED\u4FE1\u9A8C\u8BC1\u30012FA \u6216\u53EF\u4FE1\u8BBE\u5907\u7B49\u591A\u4E2A\u6062\u590D\u529F\u80FD\uFF0C\u5EFA\u8BAE\u786E\u8BA4\u4ECD\u6709\u5176\u4ED6\u53EF\u6267\u884C\u7684\u6062\u590D\u65B9\u5F0F\uFF0C\u907F\u514D\u5355\u4E00\u624B\u673A\u6210\u4E3A\u552F\u4E00\u4E0D\u53EF\u66FF\u4EE3\u7684\u6062\u590D\u6761\u4EF6\u3002</p></section><section><h3>\u5907\u7528\u6062\u590D\u8BBE\u5907\u5EFA\u8BAE</h3><p>\u5907\u7528\u6062\u590D\u8BBE\u5907\u4E0D\u5EFA\u8BAE\u628A\u8D26\u6237\u672C\u4EBA\u7684<span class="module-example-emphasis">\u4EBA\u8138\u8BC6\u522B</span>\u6216\u5176\u4ED6\u672C\u4EBA\u4E13\u5C5E\u751F\u7269\u8BC6\u522B\uFF0C\u4F5C\u4E3A\u8FDB\u5165\u5173\u952E\u6062\u590D\u5DE5\u5177\u7684\u552F\u4E00\u65B9\u5F0F\u3002</p><p>\u5982\u679C\u5907\u7528\u8BBE\u5907\u7528\u4E8E\u672A\u6765\u6062\u590D\uFF0C\u5E94\u786E\u4FDD\u672A\u6765\u6062\u590D\u4EBA\u4ECD\u53EF\u4EE5\u901A\u8FC7\u8BBE\u5907\u5BC6\u7801\u3001App \u5BC6\u7801\u3001Passkey \u6216\u5176\u4ED6\u5B89\u5168\u65B9\u5F0F\u8FDB\u5165\u90AE\u7BB1\u30012FA\u3001\u94B1\u5305\u7B49\u5173\u952E\u5DE5\u5177\u3002</p><p>\u65E5\u5E38\u4F7F\u7528\u8BBE\u5907\u4ECD\u53EF\u7EE7\u7EED\u4F7F\u7528<span class="module-example-emphasis">\u4EBA\u8138\u8BC6\u522B</span>\u7B49\u5B89\u5168\u4FDD\u62A4\uFF1B\u8FD9\u91CC\u5F3A\u8C03\u7684\u662F\uFF0C\u4E13\u95E8\u7528\u4E8E\u672A\u6765\u6062\u590D\u7684\u5907\u7528\u8BBE\u5907\uFF0C\u5E94\u907F\u514D\u672C\u4EBA\u4E13\u5C5E\u751F\u7269\u8BC6\u522B\u6210\u4E3A\u6062\u590D\u969C\u788D\u3002</p></section><section><h3>\u5982\u4F55\u5199\u6B65\u9AA4</h3><ul><li>\u4E00\u4E2A\u6B65\u9AA4\u53EA\u5199\u4E00\u4E2A\u52A8\u4F5C\uFF1B</li><li>\u6309\u987A\u5E8F\uFF1B</li><li>\u5199\u6E05\u7ED3\u679C\uFF1B</li><li>\u4E0D\u8981\u628A\u591A\u4E2A\u64CD\u4F5C\u585E\u5728\u540C\u4E00\u6B65\u3002</li></ul></section><section><h3>\u586B\u5199\u793A\u4F8B</h3><div class="module-example-cases"><article><strong>\u793A\u4F8B 1\uFF5CBinance</strong><ol><li>\u6253\u5F00\u5B98\u65B9 Binance App \u6216\u5B98\u7F51\uFF1B</li><li>\u4F7F\u7528\u6CE8\u518C\u90AE\u7BB1\u548C\u767B\u5F55\u5BC6\u7801\u8FDB\u5165\u8D26\u6237\uFF1B</li><li>\u5B8C\u6210 2FA\uFF1B</li><li>\u5982\u89E6\u53D1\u8EAB\u4EFD\u9A8C\u8BC1\uFF0C\u6309\u7167\u8D26\u6237\u8981\u6C42\u5B8C\u6210\uFF1B</li><li>\u786E\u8BA4\u8D26\u6237\u548C\u8D44\u4EA7\u53EF\u4EE5\u6B63\u5E38\u8BBF\u95EE\u3002</li></ol></article><article><strong>\u793A\u4F8B 2\uFF5CMetaMask</strong><ol><li>\u5728\u65B0\u8BBE\u5907\u5B89\u88C5\u5B98\u65B9 MetaMask\uFF1B</li><li>\u9009\u62E9\u6062\u590D\u73B0\u6709\u94B1\u5305\uFF1B</li><li>\u4F7F\u7528 Seed Phrase \u6062\u590D\uFF1B</li><li>\u8BBE\u7F6E\u65B0\u7684\u94B1\u5305\u8BBF\u95EE\u5BC6\u7801\uFF1B</li><li>\u786E\u8BA4\u94B1\u5305\u5730\u5740\u548C\u8D44\u4EA7\u4FE1\u606F\u6B63\u786E\u3002</li></ol></article><article><strong>\u793A\u4F8B 3\uFF5CLedger</strong><ol><li>\u51C6\u5907 Ledger \u8BBE\u5907\uFF1B</li><li>\u5982\u9700\u6062\u590D\u65B0\u8BBE\u5907\uFF0C\u8FDB\u5165 Restore \u6D41\u7A0B\uFF1B</li><li>\u4F7F\u7528 Seed Phrase \u5B8C\u6210\u6062\u590D\uFF1B</li><li>\u5982\u679C\u4F7F\u7528 Passphrase\uFF0C\u518D\u6062\u590D\u5BF9\u5E94\u8D26\u6237\uFF1B</li><li>\u8FDE\u63A5\u517C\u5BB9\u94B1\u5305\u8F6F\u4EF6\uFF0C\u786E\u8BA4\u5730\u5740\u6B63\u786E\u3002</li></ol></article></div></section><section><h3>\u6062\u590D\u6F14\u7EC3\u63D0\u9192</h3><p>\u5728\u6B63\u5F0F\u4FDD\u5B58\u6062\u590D\u6B65\u9AA4\u4E4B\u524D\uFF0C\u5EFA\u8BAE\u5C3D\u53EF\u80FD\u8FDB\u884C\u4E00\u6B21\u5B9E\u9645\u767B\u5F55\u68C0\u67E5\u6216\u8F7B\u91CF\u6062\u590D\u6F14\u7EC3\u3002</p><p>\u8FD9\u6837\u53EF\u4EE5\u786E\u8BA4\u8BB0\u5F55\u7684\u6B65\u9AA4\u662F\u5426\u771F\u5B9E\u53EF\u6267\u884C\uFF0C\u540C\u65F6\u5E2E\u52A9\u53D1\u73B0 Module 2 \u662F\u5426\u9057\u6F0F\u6062\u590D\u6761\u4EF6\u3001Module 3 \u662F\u5426\u9057\u6F0F\u5173\u952E\u4F4D\u7F6E\u3002</p></section>' }
};
moduleExampleContent.assistants = { title: "Module 5\uFF5C\u534F\u52A9\u4EBA\u586B\u5199\u8BF4\u660E", body: `<section><h3>\u586B\u5199\u8BF4\u660E</h3><p>\u672C\u6A21\u5757\u7528\u4E8E\u8BB0\u5F55\u672A\u6765\u6062\u590D\u8FC7\u7A0B\u4E2D\u53EF\u80FD\u63D0\u4F9B\u5E2E\u52A9\u7684\u4EBA\u6216\u673A\u6784\uFF0C\u4EE5\u53CA\u4EC0\u4E48\u65F6\u5019\u8054\u7CFB\u4ED6\u4EEC\u3001\u4ED6\u4EEC\u53EF\u4EE5\u534F\u52A9\u4EC0\u4E48\u3002</p><p>\u53EF\u4EE5\u8BB0\u5F55\u7684\u534F\u52A9\u4EBA\u5305\u62EC\u5BB6\u5EAD\u6210\u5458\u3001\u4FE1\u4EFB\u7684\u4EBA\u3001\u5F8B\u5E08\u3001\u9057\u5631\u6267\u884C\u4EBA\u3001\u53D7\u6258\u4EBA\u3001\u4F1A\u8BA1\u5E08\u3001\u7A0E\u52A1\u6216\u8D22\u5BCC\u987E\u95EE\u3001\u6280\u672F\u534F\u52A9\u4EBA\u3001\u591A\u7B7E Signer\u3001\u516C\u53F8\u6216\u5176\u4ED6\u4E13\u4E1A\u673A\u6784\u3002</p><h4>01\uFF5C\u534F\u52A9\u4EBA\u662F\u8C01</h4><p>\u8BB0\u5F55\u59D3\u540D\u6216\u673A\u6784\uFF0C\u4EE5\u53CA\u5176\u89D2\u8272\u6216\u4E0E\u8D26\u6237\u6301\u6709\u4EBA\u7684\u5173\u7CFB\u3002</p><h4>02\uFF5C\u4EC0\u4E48\u65F6\u5019\u8054\u7CFB</h4><p>\u8BF4\u660E\u672A\u6765\u6062\u590D\u4EBA\u5728\u4EC0\u4E48\u60C5\u51B5\u4E0B\u9700\u8981\u8054\u7CFB\u6B64\u4EBA\u6216\u673A\u6784\u3002</p><h4>03\uFF5C\u53EF\u4EE5\u534F\u52A9\u4EC0\u4E48</h4><p>\u8BF4\u660E\u53EF\u4EE5\u63D0\u4F9B\u7684\u5177\u4F53\u5E2E\u52A9\uFF0C\u4E0D\u8981\u53EA\u5199\u201C\u53EF\u4EE5\u5E2E\u5FD9\u201D\u3002</p><h4>04\uFF5C\u8EAB\u4EFD\u4E0E\u6743\u9650</h4><p>\u5982\u5177\u6709\u5F8B\u5E08\u3001Executor\u3001Trustee\u3001Signer\u3001\u516C\u53F8\u7BA1\u7406\u5458\u7B49\u6B63\u5F0F\u8EAB\u4EFD\uFF0C\u53EF\u8FDB\u884C\u8BF4\u660E\u3002</p><h4>05\uFF5C\u5DF2\u77E5\u6216\u53EF\u534F\u52A9\u67E5\u627E\u7684\u4FE1\u606F</h4><p>\u8BF4\u660E\u5176\u77E5\u9053\u54EA\u4E9B\u4FE1\u606F\u3001\u53EF\u4EE5\u5E2E\u52A9\u627E\u5230\u54EA\u4E9B\u6750\u6599\u3001\u8BBE\u5907\u6216\u6587\u4EF6\u3002</p><h4>06\uFF5C\u66FF\u4EE3\u8054\u7CFB\u4EBA</h4><p>\u5982\u4E3B\u8981\u534F\u52A9\u4EBA\u65E0\u6CD5\u8054\u7CFB\uFF0C\u53EF\u4EE5\u8BB0\u5F55\u5907\u7528\u8054\u7CFB\u4EBA\u6216\u673A\u6784\u3002</p><h4>07\uFF5C\u53CA\u65F6\u66F4\u65B0</h4><p>\u8054\u7CFB\u65B9\u5F0F\u3001\u89D2\u8272\u3001\u6743\u9650\u6216\u53EF\u7528\u6027\u53D1\u751F\u53D8\u5316\u65F6\uFF0C\u5E94\u53CA\u65F6\u66F4\u65B0\u3002</p><h4>\u5FC5\u8981\u63D0\u9192</h4><ul><li>\u88AB\u5217\u4E3A\u534F\u52A9\u4EBA\uFF0C\u4E0D\u4EE3\u8868\u62E5\u6709\u8D44\u4EA7\u63A7\u5236\u6743\uFF1B</li><li>\u4E0D\u5EFA\u8BAE\u4EFB\u4F55\u4E00\u4E2A\u534F\u52A9\u4EBA\u96C6\u4E2D\u638C\u63E1\u5168\u90E8\u63A7\u5236\u6750\u6599\uFF1B</li><li>\u5B8C\u6574 Seed Phrase / \u52A9\u8BB0\u8BCD\u548C\u5B8C\u6574 Private Key / \u79C1\u94A5\u4E0D\u5E94\u4EA4\u7ED9\u4EFB\u4F55\u534F\u52A9\u4EBA\u3002</li></ul><p>\u5982\u679C\u6587\u5B57\u4E0D\u8DB3\uFF0C\u53EF\u4F7F\u7528\u6587\u5B57\u6587\u4EF6\u3001\u56FE\u7247\u3001\u6587\u6863\u3001\u8BED\u97F3\u7559\u8A00\u7B49\u9644\u4EF6\u8865\u5145\u3002</p><p>\u5982\u679C\u4E0D\u9700\u8981\u534F\u52A9\u4EBA\uFF0C\u53EF\u4EE5\u660E\u786E\u9009\u62E9\u201C\u4E0D\u9700\u8981\u201D\u3002</p></section>` };
moduleExampleContent.message = { title: "Module 6\uFF5C\u7ED9\u672A\u6765\u6062\u590D\u4EBA\u7684\u5631\u6258\u586B\u5199\u8BF4\u660E", body: `<section><h3>\u586B\u5199\u8BF4\u660E</h3><p>\u672C\u6A21\u5757\u7528\u4E8E\u7559\u4E0B\u524D\u9762\u51E0\u4E2A\u6A21\u5757\u65E0\u6CD5\u5B8C\u6574\u8868\u8FBE\u7684\u91CD\u8981\u63D0\u9192\u3001\u4E2A\u4EBA\u5B89\u6392\uFF0C\u4EE5\u53CA\u4F60\u771F\u6B63\u60F3\u5BF9\u672A\u6765\u6062\u590D\u4EBA\u8BF4\u7684\u8BDD\u3002</p><p>\u4F60\u53EF\u4EE5\u8BF4\u660E\u9700\u8981\u7279\u522B\u6CE8\u610F\u7684\u4E8B\u60C5\u548C\u7279\u6B8A\u80CC\u666F\uFF0C\u4E5F\u53EF\u4EE5\u7559\u4E0B\u4F60\u5BF9\u8D22\u5BCC\u3001\u5BB6\u5EAD\u3001\u8D23\u4EFB\u548C\u4EBA\u751F\u7684\u7406\u89E3\u3002</p><p>\u8FD9\u91CC\u6CA1\u6709\u6807\u51C6\u7B54\u6848\uFF0C\u4E5F\u4E0D\u8981\u6C42\u5168\u90E8\u586B\u5199\u3002</p><p>\u4F60\u53EF\u4EE5\u53EA\u7559\u4E0B\u51E0\u53E5\u8BDD\uFF0C\u4E5F\u53EF\u4EE5\u901A\u8FC7\u6587\u5B57\u3001\u56FE\u7247\u3001\u7167\u7247\u3001\u8BED\u97F3\u7559\u8A00\u6216\u89C6\u9891\u7559\u4E0B\u66F4\u5B8C\u6574\u7684\u8868\u8FBE\u3002</p><p><strong>\u6709\u4E9B\u8D22\u5BCC\u53EF\u4EE5\u88AB\u8F6C\u79FB\uFF0C\u6709\u4E9B\u4EF7\u503C\u53EA\u80FD\u88AB\u4F20\u9012\u3002</strong></p><p>\u9664\u4E86\u5E2E\u52A9\u672A\u6765\u6062\u590D\u4EBA\u7406\u89E3\u8FD9\u4E9B\u8D44\u4EA7\uFF0C\u4E5F\u53EF\u4EE5\u8BA9\u4ED6\u4EEC\u7406\u89E3\u4F60\u4E3A\u4EC0\u4E48\u8FD9\u6837\u5B89\u6392\uFF0C\u4EE5\u53CA\u4F60\u771F\u6B63\u5E0C\u671B\u7559\u4E0B\u4EC0\u4E48\u3002</p><h4>01\uFF5C\u91CD\u8981\u63D0\u9192\u4E0E\u7279\u6B8A\u5B89\u6392</h4><p>\u8BB0\u5F55\u524D\u9762\u6A21\u5757\u96BE\u4EE5\u8868\u8FBE\u3001\u4F46\u672A\u6765\u6062\u590D\u4EBA\u786E\u5B9E\u9700\u8981\u77E5\u9053\u7684\u91CD\u70B9\u3002</p><h4>02\uFF5C\u5173\u4E8E\u8FD9\u4E9B\u8D44\u4EA7\u4E0E\u8D22\u5BCC\uFF0C\u6211\u60F3\u7559\u4E0B\u7684\u60F3\u6CD5</h4><p>\u53EF\u4EE5\u5199\u8FD9\u4E9B\u8D44\u4EA7\u4E3A\u4EC0\u4E48\u91CD\u8981\u3001\u4F60\u5982\u4F55\u7406\u89E3\u8D22\u5BCC\uFF0C\u4EE5\u53CA\u4F60\u5E0C\u671B\u5B83\u4EEC\u672A\u6765\u53D1\u6325\u4EC0\u4E48\u4EF7\u503C\u3002</p><h4>03\uFF5C\u6211\u6700\u60F3\u5BF9\u4F60\u8BF4\u7684\u8BDD</h4><p>\u53EF\u4EE5\u662F\u4E00\u6BB5\u8BDD\u3001\u4E00\u5C01\u4FE1\uFF0C\u6216\u4EFB\u4F55\u771F\u6B63\u5E0C\u671B\u672A\u6765\u6062\u590D\u4EBA\u3001\u5BB6\u4EBA\u6216\u91CD\u8981\u7684\u4EBA\u770B\u5230\u7684\u5185\u5BB9\u3002</p><h4>04\uFF5C\u7559\u4E0B\u6587\u5B57\uFF0C\u4E5F\u53EF\u4EE5\u7559\u4E0B\u58F0\u97F3\u548C\u5F71\u50CF</h4><p>\u5982\u6587\u5B57\u4E0D\u8DB3\uFF0C\u53EF\u4EE5\u901A\u8FC7\u56FE\u7247\u3001\u7167\u7247\u3001\u8BED\u97F3\u7559\u8A00\u6216\u89C6\u9891\u8865\u5145\u3002</p><p><strong>\u7559\u4E0B\u7684\u4E0D\u53EA\u662F\u4FE1\u606F\uFF0C\u4E5F\u53EF\u4EE5\u662F\u4F60\u7684\u58F0\u97F3\u3002</strong></p><h4>05\uFF5C\u66F4\u65B0\u4E0E\u786E\u8BA4</h4><p>\u5F53\u91CD\u8981\u5B89\u6392\u3001\u8D26\u6237\u72B6\u6001\u6216\u9644\u4EF6\u53D1\u751F\u53D8\u5316\u540E\uFF0C\u8BF7\u53CA\u65F6\u66F4\u65B0\u76F8\u5173\u5185\u5BB9\u3002</p><p>\u4E0D\u8981\u5728\u672C\u6A21\u5757\u76F4\u63A5\u5199\u5165\u5B8C\u6574 Seed Phrase / \u52A9\u8BB0\u8BCD\u3001Private Key / \u79C1\u94A5\u3001OTP\u3001Authenticator Seed \u6216\u5B8C\u6574\u5BC6\u7801\u3002</p><p>\u5982\u6D89\u53CA\u6700\u7EC8\u8D44\u4EA7\u5F52\u5C5E\u3001\u9057\u5631\u3001\u4FE1\u6258\u6216\u5176\u4ED6\u6CD5\u5F8B\u5206\u914D\u4E8B\u9879\uFF0C\u4EE5\u6B63\u5F0F\u751F\u6548\u7684\u6CD5\u5F8B\u6587\u4EF6\u4E3A\u51C6\u3002</p></section>` };
