var expandableTemplateNote = "<section><h3>\u9644\u4EF6\u4E0A\u4F20</h3><p>\u53EF\u4E0A\u4F20\u6587\u6863\u3001\u56FE\u7247\u3001\u8BED\u97F3\u3001\u89C6\u9891\u7B49\u8D44\u6599\u3002\u5355\u4E2A\u6587\u4EF6\u4E0D\u8D85\u8FC7 10 MB\uFF0C\u5F53\u524D Recovery Map \u9644\u4EF6\u603B\u7A7A\u95F4\u4E3A 50 MB\u3002</p></section><section><h3>\u6A21\u677F\u6269\u5C55</h3><p>\u5982\u679C\u9884\u7559\u8868\u683C\u7A7A\u95F4\u4E0D\u8DB3\uFF0C\u53EF\u4EE5\u5728 Word \u4E2D\u7EE7\u7EED\u6DFB\u52A0\u884C\u6216\u5217\uFF0C\u6309\u5B9E\u9645\u9700\u8981\u6269\u5C55\u586B\u5199\u533A\u57DF\u3002</p></section>";
