var directBackupDeviceAdvice = '<section><h3>\u5907\u7528\u6062\u590D\u8BBE\u5907\u5EFA\u8BAE</h3><p>\u5907\u7528\u6062\u590D\u8BBE\u5907\u4E0D\u5EFA\u8BAE\u628A\u8D26\u6237\u672C\u4EBA\u7684<span class="module-example-emphasis">\u4EBA\u8138\u8BC6\u522B</span>\u6216\u5176\u4ED6<span class="module-example-emphasis">\u672C\u4EBA\u4E13\u5C5E\u751F\u7269\u8BC6\u522B</span>\uFF0C\u4F5C\u4E3A\u8FDB\u5165\u5173\u952E\u6062\u590D\u5DE5\u5177\u7684<span class="module-example-emphasis">\u552F\u4E00\u65B9\u5F0F</span>\u3002</p><p>\u5982\u679C\u5907\u7528\u8BBE\u5907\u7528\u4E8E\u672A\u6765\u6062\u590D\uFF0C\u5E94\u786E\u4FDD\u672A\u6765\u6062\u590D\u4EBA\u4ECD\u53EF\u4EE5\u901A\u8FC7\u8BBE\u5907\u5BC6\u7801\u3001App \u5BC6\u7801\u3001Passkey \u6216\u5176\u4ED6\u5B89\u5168\u65B9\u5F0F\u8FDB\u5165\u90AE\u7BB1\u30012FA\u3001\u94B1\u5305\u7B49\u5173\u952E\u5DE5\u5177\u3002</p></section>';
moduleExampleContent.locations.body = moduleExampleContent.locations.body.replace(/<section><h3>恢复设备建议<\/h3>[\s\S]*?<\/section>$/, directBackupDeviceAdvice);
