function renderRecoveryGuide() {
  const modules = Object.entries(guideDetails).map(([id, item], index) => `<section class="guide-accordion-item" data-guide-accordion="${id}"><button class="guide-accordion-trigger" type="button" aria-expanded="false" aria-controls="guide-panel-${id}"><span class="guide-accordion-number">${String(index + 1).padStart(2, "0")}</span><span class="guide-accordion-heading"><strong>${labels[id]}</strong><small>${item.value}</small></span><span class="guide-accordion-indicator" aria-hidden="true"></span></button><div class="guide-accordion-panel" id="guide-panel-${id}" hidden><div class="guide-detail-grid"><section><h3>\u4F60\u5C06\u6574\u7406\u4EC0\u4E48</h3><ul>${item.items.slice(0, 6).map((point) => `<li>${escape(point)}</li>`).join("")}</ul></section><section><h3>\u8FD9\u4E2A\u6A21\u5757\u89E3\u51B3\u4EC0\u4E48</h3><p>${item.benefit}</p><aside><b>\u6CE8\u610F</b><span>${item.notice}</span></aside></section></div></div></section>`).join("");
  const path = [["WHAT", "\u6709\u4EC0\u4E48"], ["REQUIREMENTS", "\u9700\u8981\u4EC0\u4E48"], ["LOCATION", "\u5728\u54EA\u91CC"], ["STEPS", "\u600E\u4E48\u505A"], ["HELP", "\u8C01\u534F\u52A9"], ["INSTRUCTIONS", "\u7559\u4E0B\u4EC0\u4E48\u8BF4\u660E"]];
  app.innerHTML = `<section class="recovery-guide-page"><header class="guide-intro"><p class="eyebrow">RECOVERY MAP GUIDE</p><h1><span>\u91CD\u8981\u7684\u8D44\u4EA7\u6062\u590D\u4FE1\u606F\uFF0C\u4E0D\u5E94\u53EA\u7559\u5728\u4F60\u7684\u8BB0\u5FC6\u91CC\u3002</span><span>\u8BA9\u672A\u6765\u7684\u4F60\uFF0C\u548C\u4F60\u6307\u5B9A\u7684\u6062\u590D\u4EBA\uFF0C\u90FD\u80FD\u627E\u5230\u3002</span></h1><div class="guide-lead"><p>\u91CD\u8981\u6570\u5B57\u8D44\u4EA7\u3001\u8D26\u6237\u548C\u8EAB\u4EFD\u4FE1\u606F\u5F80\u5F80\u5206\u6563\u5728\u4E0D\u540C\u5E73\u53F0\u3001\u8BBE\u5907\u548C\u4F4D\u7F6E\uFF0C\u800C\u771F\u6B63\u5F71\u54CD\u6062\u590D\u7684\uFF0C\u662F\u8D44\u4EA7\u5728\u54EA\u91CC\u3001\u9700\u8981\u4EC0\u4E48\u6761\u4EF6\u3001\u5173\u952E\u8D44\u6599\u5728\u54EA\u91CC\uFF0C\u4EE5\u53CA\u5E94\u8BE5\u5148\u505A\u4EC0\u4E48\u3002</p><p>SKREK \u901A\u8FC7\u516D\u4E2A\u76F8\u4E92\u5173\u8054\u7684\u6A21\u5757\uFF0C\u628A\u8FD9\u4E9B\u4FE1\u606F\u6574\u7406\u6210\u4E00\u6761\u6E05\u6670\u3001\u53EF\u6267\u884C\u7684 Recovery Map\u3002</p></div><button class="guide-top-cta" id="guide-start-top">\u5F00\u59CB\u5EFA\u7ACB Recovery Map <span>\u2192</span></button></header><section class="guide-definition"><p class="eyebrow">A COMPLETE RECOVERY PATH</p><h2>Recovery Map \u4E0D\u662F\u4E00\u4EFD\u8D44\u4EA7\u6E05\u5355\u3002</h2><p>\u5B83\u628A\u8D44\u4EA7\u3001\u6062\u590D\u6761\u4EF6\u3001\u8D44\u6599\u4F4D\u7F6E\u3001\u64CD\u4F5C\u6B65\u9AA4\u548C\u534F\u52A9\u5173\u7CFB\u8FDE\u63A5\u8D77\u6765\uFF0C\u8BA9\u672A\u6765\u771F\u6B63\u9700\u8981\u6062\u590D\u7684\u4EBA\u77E5\u9053\u4ECE\u54EA\u91CC\u5F00\u59CB\u3002</p></section><section class="guide-path" aria-label="Recovery Path">${path.map(([en, zh], index) => `<div><small>${en}</small><strong>${zh}</strong>${index < path.length - 1 ? '<span aria-hidden="true">\u2192</span>' : ""}</div>`).join("")}</section><section class="guide-modules-overview" id="guide-modules"><header class="guide-modules-heading"><p class="eyebrow">SIX MODULES</p><h2>\u516D\u4E2A\u6A21\u5757\uFF0C\u7EC4\u6210\u4E00\u6761\u5B8C\u6574\u7684\u6062\u590D\u8DEF\u5F84</h2><p>\u4ECE\u201C\u6709\u4EC0\u4E48\u201D\uFF0C\u5230\u201C\u5728\u54EA\u91CC\u3001\u9700\u8981\u4EC0\u4E48\u3001\u600E\u4E48\u6062\u590D\u3001\u8C01\u80FD\u534F\u52A9\u201D\uFF0C\u516D\u4E2A\u6A21\u5757\u5171\u540C\u5B8C\u6210 Recovery Map\u3002</p></header><div class="guide-accordion">${modules}</div></section><section class="guide-footer"><div class="guide-values"><p><b>Recovery Clues</b><span>\u8BB0\u5F55\u6062\u590D\u7EBF\u7D22\uFF0C\u4E0D\u96C6\u4E2D\u4FDD\u5B58\u6838\u5FC3\u79D8\u5BC6</span></p><p><b>Recovery Ready</b><span>\u8BA9\u672A\u6765\u7684\u4F60\u548C\u6307\u5B9A\u6062\u590D\u4EBA\u77E5\u9053\u4ECE\u54EA\u91CC\u5F00\u59CB</span></p><p><b>Keep It Current</b><span>\u5F53\u8D44\u4EA7\u548C\u6062\u590D\u6761\u4EF6\u53D8\u5316\u65F6\uFF0C\u53CA\u65F6\u66F4\u65B0</span></p></div><div class="guide-primary"><button id="guide-start">\u5F00\u59CB\u5EFA\u7ACB Recovery Map <span>\u2192</span></button><button class="guide-knowledge-link" id="guide-knowledge">\u67E5\u770B\u8BE6\u7EC6\u586B\u5199\u6307\u5357 \u2192</button></div></section></section>`;
  const accordionItems = [...document.querySelectorAll("[data-guide-accordion]")];
  accordionItems.forEach((item) => item.querySelector(".guide-accordion-trigger").onclick = () => {
    const open = !item.classList.contains("is-open");
    accordionItems.forEach((entry) => {
      entry.classList.remove("is-open");
      entry.querySelector(".guide-accordion-trigger").setAttribute("aria-expanded", "false");
      entry.querySelector(".guide-accordion-panel").hidden = true;
    });
    if (open) {
      item.classList.add("is-open");
      item.querySelector(".guide-accordion-trigger").setAttribute("aria-expanded", "true");
      item.querySelector(".guide-accordion-panel").hidden = false;
    }
  });
  document.querySelector("#guide-start-top").onclick = document.querySelector("#guide-start").onclick = () => navTo("purchase-plans");
  document.querySelector("#guide-knowledge").onclick = () => {
    location.href = "../v3-crypto/index.html#knowledge";
  };
}
